// === Tab: mySketch ===
let simplex

function setup() {
	createCanvas(windowWidth, windowHeight);
	rs = random(10000)
	simplex = new OpenSimplexNoise(Date.now());
}

function draw() {
	background(255);

	//flower
	fill(0, 30)
	noStroke()
	for (let j = 0; j < 16; j += 0.5) {
		push()
		translate(width / 2, height / 2)
		rotate(j)
		beginShape()
		let d = map(simplex.noise2D(j / 3, millis() / 2000), -1, 1, height / 6, height / 2)
		let inc = TWO_PI / 13
		for (let i = 0; i <= TWO_PI; i += inc) {
			let xer = cos(i) * d
			let yer = sin(i) * d
			let midxer = cos(i + inc / 2) * (d / 3)
			let midyer = sin(i + inc / 2) * (d / 3)
			curveVertex(xer, yer)
			curveVertex(midxer, midyer)
		}
		curveVertex(cos(0) * d, sin(0) * d)
		endShape()
		pop()
	}
}

